def clean(df):
    df = df.copy()
    # clean Category: strip whitespace and fix typos
    if 'Category' in df.columns:
        df['Category'] = df['Category'].apply(lambda x: x.strip() if isinstance(x, str) else x)
        df['Category'] = df['Category'].replace({'Furnture': 'Furniture', 'Accesories': 'Accessories'})
    # remove exact duplicate rows
    df = df.drop_duplicates()
    # ensure Order_ID uniqueness (keep first)
    if 'Order_ID' in df.columns:
        df = df.drop_duplicates(subset=['Order_ID'], keep='first')
    return df

def answer(df):
    # count orders per Category, drop missing group keys
    if 'Category' not in df.columns:
        return {}
    d = df.dropna(subset=['Category'])
    # exclude empty strings if any
    d = d[d['Category'].astype(str).str.strip() != '']
    counts = d.groupby('Category').size()
    return {str(k): int(v) for k, v in counts.items()}
